mapper.select:
SELECT * FROM (
SELECT ROW_NUMBER() OVER (ORDER BY A.CHCK_STRT_DT DESC, A.LAST_MDF_DT DESC) AS LISTNUM,
SELECT ROW_NUMBER() OVER (ORDER BY A.LAST_MDF_DT DESC, A.CHCK_STRT_DT DESC) AS LISTNUM,
A.PWPL_ID, A.CHCK_SNO, A.PRCDOC_SNO, TO_CHAR(CHCK_STRT_DT, 'YYYY-MM-DD') AS CHCK_STRT_DT, TO_CHAR(CHCK_END_DT, 'YYYY-MM-DD') AS CHCK_END_DT, TO_CHAR(CHCK_STRT_DT, 'YYYY-MM-DD') || ' ~ ' || TO_CHAR(CHCK_END_DT, 'YYYY-MM-DD') AS CHCK_DT, A.CHCK_TITL, A.WRKOR_NO, A.CHKPR_ID, A.CHKPR_FNM, A.CNMR_ID, A.CNMR_FNM, A.AAWPR_ID, A.AAWPR_FNM, A.ATWT_RQST_YN, A.PRCDOC_RVSN_NO, A.PRSTS_CFY, CASE WHEN A.PRSTS_CFY = 'R' THEN '준비' WHEN A.PRSTS_CFY = 'A' THEN '허가' WHEN A.PRSTS_CFY = 'F' THEN '수행' WHEN A.PRSTS_CFY = 'S' THEN '정지' WHEN A.PRSTS_CFY = 'C' THEN '완료' ELSE '' END AS PRSTS_CFY_NM, C.PRCDOC_NO, C.PRCDOC_NM, C.DOC_TYP_CD, C.PRT_NO, (SELECT TO_CHAR(RG_DT, 'YYYY-MM-DD HH24:MI:SS') FROM GE_PL_CHCK0101_D WHERE CHCK_SNO = A.CHCK_SNO) FM_RG_DT FROM GE_PL_CHCK01_M A JOIN GE_PL_PRCDOC01_M C ON A.PRCDOC_SNO = C.PRCDOC_SNO
AND C.PRCDOC_NO LIKE '%'||#{PRCDOC_NO}||'%'
AND C.PRCDOC_NM LIKE '%'||#{PRCDOC_NM}||'%'
WHERE A.DLT_YN = 'N'
AND A.CHKPR_ID = #{CHKPR_ID}
AND A.CHCK_STRT_DT >= #{CHCK_STRT_DT}
AND A.CHCK_END_DT <= #{CHCK_END_DT}
AND A.PRSTS_CFY IN ('R','F')
AND A.PRSTS_CFY = #{PRSTS_CFY}
AND A.CHCK_TITL LIKE '%'||#{CHCK_TITL}||'%'
) WHERE LISTNUM BETWEEN #{DISPSTART} AND #{DISPEND}

SELECT COUNT(*) FROM GE_PL_CHCK01_M A JOIN GE_PL_PRCDOC01_M C ON A.PRCDOC_SNO = C.PRCDOC_SNO
AND C.PRCDOC_NO LIKE '%'||#{PRCDOC_NO}||'%'
AND C.PRCDOC_NM LIKE '%'||#{PRCDOC_NM}||'%'
WHERE A.DLT_YN = 'N'
AND A.CHKPR_ID = #{CHKPR_ID}
AND A.CHCK_STRT_DT >= #{CHCK_STRT_DT}
AND A.CHCK_END_DT <= #{CHCK_END_DT}
AND A.PRSTS_CFY IN ('R','F')
AND A.PRSTS_CFY = #{PRSTS_CFY}
AND A.CHCK_TITL LIKE '%'||#{CHCK_TITL}||'%'

mapper.update:
UPDATE GE_PL_CHCK01_M
   SET PRSTS_CFY 	= #{PRSTS_CFY}
 WHERE CHCK_SNO = #{CHCK_SNO}

UPDATE GE_PL_CHCK0101_D
   SET WRTE_JSON_DCR = #{WRTE_JSON_DCR},
	   RG_DT 	 = SYSDATE
 WHERE CHCK_SNO = #{CHCK_SNO}
   AND ATFL_NO = #{ATFL_NO}

mapper.delete:
DELETE GE_PL_CHCK0101_D
 WHERE CHCK_SNO = #{CHCK_SNO}
   AND ATFL_NO = #{ATFL_NO}
